create table if not exists public.notes(id uuid primary key default gen_random_uuid(),title text not null default '',body text not null,created_at timestamptz not null default now(),likes integer not null default 0);alter table public.notes enable row level security;create policy "public can read notes" on public.notes for select using(true);create policy "public can create notes" on public.notes for insert with check(length(body)>0 and length(body)<=5000 and length(title)<=120);create policy "public can like notes" on public.notes for update using(true) with check(likes>=0);